export type GapPathRow = {
  year: number;
  muniPsPct: number;
  statePsPct: number;
  teacherPct: number;
  stateEmpPct: number;
  confidence: Confidence;
};

/** Two-point Equable path + desk interpolation marker for viz. */
export const WEIGHTED_GAP_PATH: GapPathRow[] = [
  {
    year: 2023,
    muniPsPct: 75.3,
    statePsPct: 75.3,
    teacherPct: 73.1,
    stateEmpPct: 63.3,
    confidence: "disclosed",
  },
