"use client";

import { useMemo, useState } from "react";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  ReferenceLine,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  HEADLINE,
  SOURCE_NOTE,
  WEIGHTED_GAP_PATH,
  binCounts,
  cohortMedianLadder,
  fmt1,
  fmtPct,
  fmtPp,
  plansByCohort,
  scatterPoints,
  typeSplitsForYear,
  weightedGapBars,
  type PlanCohort,
} from "@/data/local-police-fire-plan-underfunding-2026-data";

// viz-types: weighted gap bars, median ladder bars, funded-bin grouped bars, funded??liability scatter, type-path composed lines | layout: default

type ViewId = "gaps" | "medians" | "bins" | "scatter" | "path";
type SampleFilter = "all-public-safety" | "muni-public-safety" | "teacher" | "state-employee";
type YearId = 2023 | 2024;

const NAVY = "#0f172a";
const TEAL = "#0d9488";
const AMBER = "#d97706";
const ROSE = "#e11d48";
const INDIGO = "#4f46e5";
const SLATE = "#64748b";
const EMERALD = "#059669";

const COHORT_COLORS: Record<string, string> = {
  "muni-public-safety": ROSE,
  "state-public-safety": AMBER,
  teacher: INDIGO,
  "state-employee": SLATE,
  "muni-civilian": TEAL,
  "all-public-safety": ROSE,
};

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle ? (
          <p className="mt-1 text-sm text-slate-500">{subtitle}</p>
        ) : null}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string | number>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={String(o.id)}
            type="button"
            onClick={() => onChange(o.id)}
            className={
              "rounded-md px-3 py-1.5 text-sm font-medium transition-colors " +
              (value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50")
            }
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

