  const [view, setView] = useState<ViewId>("gaps");
  const [year, setYear] = useState<YearId>(2024);
  const [sample, setSample] = useState<SampleFilter>("all-public-safety");

  const gapBars = useMemo(() => weightedGapBars(year), [year]);
